class Job:
    def __init__(self, id, c_min, c_max, r_min, r_max, deadline, priority):
        self.id = id
        self.c_min = c_min
        self.c_max = c_max
        self.r_min = r_min
        self.r_max = r_max
        self.deadline = deadline # relative deadline
        self.priority = priority

class ExecutionScenario:
    def __init__(self, job_set):
        self.job_execution_times = {}
        self.job_release_times = {}
        self.job_set = job_set

    def generate_valid_scenario(self):
        import random
        for job in self.job_set:
            self.job_execution_times[job.id] = random.uniform(job.c_min, job.c_max)
            self.job_release_times[job.id] = random.uniform(job.r_min, job.r_max)
        return self # Returns a specific scenario instance

def is_priority_eligible(job_j, current_time, jobs_in_path_P, all_jobs):
    if job_j.id in jobs_in_path_P:
        return False

    if job_j.r_min > current_time:
        return False

    for job_x in all_jobs:
        if job_x.id in jobs_in_path_P or job_x.id == job_j.id:
            continue

        if job_x.r_max <= current_time and job_x.priority < job_j.priority:
            return False # A higher-priority job_x is certainly released and pending

    return True

def is_iip_eligible(job_j, current_time, jobs_in_path_P, iip_function_L):
    # iip_function_L is the L(J_i, t, J_S) function
    return current_time <= iip_function_L(job_j, current_time, jobs_in_path_P)

def is_potentially_next(job_j, current_time_t, l_i, jobs_in_path_P, all_jobs, iip_function_L):
    # Clause (i)
    if job_j.r_min <= l_i:
        return True

    # Clause (ii)
    for job_x in all_jobs:
        if job_x.id in jobs_in_path_P or job_x.id == job_j.id:
            continue

        if job_x.r_max < current_time_t:
            check_time = max(job_x.r_max, l_i)
            if is_priority_eligible(job_x, check_time, jobs_in_path_P, all_jobs) and \
               is_iip_eligible(job_x, check_time, jobs_in_path_P, iip_function_L):
                return False # Another job_x would be scheduled before job_j
    return True

def is_eligible_successor(job_j, path_P, vertex_v_i, all_jobs, iip_function_L):
    jobs_in_path_P = path_P.get_jobs_in_sequence()
    e_i = vertex_v_i.eft
    l_i = vertex_v_i.lft
    t_E = max(e_i, job_j.r_min)

    if job_j.id in jobs_in_path_P:
        return False

    if not is_iip_eligible(job_j, t_E, jobs_in_path_P, iip_function_L):
        return False
    if not is_priority_eligible(job_j, t_E, jobs_in_path_P, all_jobs):
        return False
    if not is_potentially_next(job_j, t_E, l_i, jobs_in_path_P, all_jobs, iip_function_L):
        return False

    return True

def paths_match(path_Q, path_P):
    jobs_in_Q = set(path_Q.get_jobs_in_sequence())
    jobs_in_P = set(path_P.get_jobs_in_sequence())

    if jobs_in_Q != jobs_in_P:
        return False

    v_q = path_Q.get_last_vertex()
    v_p = path_P.get_last_vertex()

    # Intervals overlap if max(e_q, e_p) <= min(l_q, l_p)
    if max(v_q.eft, v_p.eft) <= min(v_q.lft, v_p.lft):
        return True
    else:
        return False

def calculate_t_L(prev_vertex_lft, job_j_r_max):
    t_L = max(prev_vertex_lft, job_j_r_max)
    return t_L

def calculate_t_H(job_j, jobs_in_path_P, all_jobs):
    higher_priority_pending_jobs = [
        job_x for job_x in all_jobs
        if job_x.id not in jobs_in_path_P and job_x.priority < job_j.priority
    ]
    if not higher_priority_pending_jobs:
        return float('inf')
    else:
        min_r_max_x = min(job_x.r_max for job_x in higher_priority_pending_jobs)
        return min_r_max_x - 1

def merge_vertex_intervals(vertex_v_p, vertex_v_q):
    vertex_v_p.eft = min(vertex_v_p.eft, vertex_v_q.eft)
    vertex_v_p.lft = max(vertex_v_p.lft, vertex_v_q.lft)

def calculate_bcrt(job_j, schedule_graph):
    min_finish_time = float('inf')
    # A_j is the set of vertices where job_j is the *last* job on the path
    for vertex_v_p in schedule_graph.get_completion_vertices_for_job(job_j):
        min_finish_time = min(min_finish_time, vertex_v_p.eft)

    if min_finish_time == float('inf'):
        return float('inf') # Job never finishes
    return min_finish_time - job_j.r_min

def is_job_set_hard_real_time_schedulable(job_set, wcrt_values):
    for job_j in job_set:
        if wcrt_values[job_j.id] > job_j.deadline: # Assuming job.deadline is relative deadline
            return False # Job J_j misses its deadline
    return True

class Task:
    def __init__(self, id, period, c_max):
        self.id = id
        self.period = period
        self.c_max = c_max

def check_np_necessary_condition(task_set):
    if not task_set:
        return True

    # Find task with shortest period
    task_1 = min(task_set, key=lambda t: t.period)
    T_1 = task_1.period
    C_max_1 = task_1.c_max

    for task_i in task_set:
        if task_i.id == task_1.id:
            continue
        if task_i.c_max > 2 * (T_1 - C_max_1):
            return False # Condition violated
    return True # Condition satisfied (but not necessarily schedulable)
